{ // H1: Resolved_business_contact_is_used_in_statement_and_summary
var originalCulture = CultureInfo.CurrentCulture;
try
{
    CultureInfo.CurrentCulture = CultureInfo.InvariantCulture;
    var builder = new StatementBuilder();
    var account = new Account
    {
        Id = "ACME",
        Name = "Acme Corp",
        Kind = AccountKind.Business
    };
    var invoices = new List<Invoice>
    {
        new Invoice
        {
            Number = "INV-1",
            Lines = new List<InvoiceLine>
            {
                new InvoiceLine { NetAmount = 100m },
                new InvoiceLine { NetAmount = 20m }
            }
        },
        new Invoice
        {
            Number = "INV-2",
            Lines = new List<InvoiceLine>
            {
                new InvoiceLine { NetAmount = 30m }
            }
        }
    };

    var contact = builder.ResolveContact(account);
    var statement = builder.BuildStatement(account, invoices);
    var summary = builder.AppendSummary(account);

    Check.Equal("ap+ACME@example.com", contact);
    Check.Equal("STATEMENT FOR Acme Corp\ncontact: ap+ACME@example.com\nINV-1: 120\nINV-2: 30\nTOTAL 150", statement);
    Check.Equal("summary: Acme Corp (biz)", summary);
}
finally
{
    CultureInfo.CurrentCulture = originalCulture;
}
}
